---

### 4. NEXT.CONFIG.TS (FULL)

```typescript
import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  output: "standalone",
  images: {
    dangerouslyAllowSVG: true,
    contentDispositionType: "attachment",
    contentSecurityPolicy: "default-src 'self'; script-src 'none'; sandbox;",
    unoptimized: process.env.NODE_ENV === "development",
    remotePatterns: [
      {
        protocol: "https",
        hostname: "cdn.sanity.io",
      },
      {
        protocol: "https",
        hostname: "cdn.prod.website-files.com",
      },
    ],
  },
};

export default nextConfig;
```

**Key Config Details:**
- Standalone output mode (self-contained deployment)
- SVG support enabled with security constraints
- Image optimization disabled in development
- Remote images from Sanity CMS and Webflow CDN allowed

---

### 5. SRC/APP/GLOBALS.CSS (FIRST 50 LINES)

Uses **Tailwind CSS v4** with custom configuration:

```css
@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  /* RoobertPRO font */
  --font-roobert: var(--font-roobert);
  --font-sans: var(--font-roobert);
  --font-mono: var(--font-roobert);
  --font-heading: var(--font-roobert);

  /* Boldteq Brand Colors */
  --color-brand-navy: #092245;
  --color-brand-navy-deep: #082753;
  --color-brand-cyan: #21cfff;
  --color-brand-blue: #019ae6;
  --color-brand-yellow: #FFEB85;
  --color-brand-dark: #111827;
  --color-brand-dark-alt: #1a1925;
  --color-brand-green: #3c7c43;
  --color-brand-green-badge: #18c958;
  --color-brand-light-blue: #ecf7fd;
  --color-brand-light-bg: #f5f7fa;
  --color-brand-gray-bg: #f7f7f8;
  --color-brand-card-hover: #cdebfa;
  --color-brand-card-border: #009ce0;

  /* shadcn semantic tokens */
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
```

**CSS Strategy:** Tailwind with shadcn component library, custom brand color tokens, RoobertPRO as primary font family.

---

